import { useState } from 'react';
import { settingsApi } from '../../services/settingsApi';

const DEFAULT_TAX_RATES = {
  qst: '9.975',
  gst: '5',
};

export default function SystemSettings() {
  const [taxRates, setTaxRates] = useState(DEFAULT_TAX_RATES);
  const [isSaving, setIsSaving] = useState(false);
  const [status, setStatus] = useState({ type: '', message: '' });

  const handleChange = (field) => (event) => {
    setTaxRates((prev) => ({ ...prev, [field]: event.target.value }));
  };

  const handleSave = async (event) => {
    event.preventDefault();
    setIsSaving(true);
    setStatus({ type: '', message: '' });

    try {
      await settingsApi.updateSettings({
        qst: parseFloat(taxRates.qst),
        gst: parseFloat(taxRates.gst),
      });
      setStatus({ type: 'success', message: 'Tax settings saved.' });
    } catch (error) {
      setStatus({
        type: 'error',
        message: error?.message || 'Unable to save tax settings.',
      });
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <section className=\"bg-card-light dark:bg-card-dark rounded-3xl shadow-sm border border-gray-100 dark:border-gray-800 p-6\">
